# Let's see if filling holes (0s surrounded by 8s) makes sense
# A 0 is a "hole" if all its orthogonal neighbors that exist are 8 (or boundary)
def fill_holes(grid):
    rows = len(grid)
    cols = len(grid[0])
    filled = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                # Check if this 0 is "trapped" by 8s
                neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
                has_0_neighbor = False
                for nr, nc in neighbors:
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 0:
                            has_0_neighbor = True
                            break
                if not has_0_neighbor:
                    # This 0 has no 0 neighbors - it's completely surrounded by 8s
                    filled[r][c] = 8

    return filled

